import java.io.*;
import java.util.*;

public class Main {
    // 计算 a 排成 b 的最大保留和
    static long calc(long[] a, long[] b) {
        Map<Long, Integer> cnt = new HashMap<>();
        long diff = 0, keep = 0;
        for (int i = 0; i < a.length; i++) {
            long x = a[i], y = b[i];
            // a 前缀插入 x
            int before = cnt.getOrDefault(x, 0);
            if (before != 0) diff--;
            int after = before + 1;
            cnt.put(x, after);
            if (after != 0) diff++;
            // b 前缀移除 y
            before = cnt.getOrDefault(y, 0);
            if (before != 0) diff--;
            after = before - 1;
            cnt.put(y, after);
            if (after != 0) diff++;
            // 若前缀一致且 a[i]==b[i]，则可保留
            if (diff == 0 && x == y) {
                keep += x;
            }
        }
        return keep;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(in.readLine());
        long[] a = new long[n];
        StringTokenizer st = new StringTokenizer(in.readLine());
        long sum = 0;
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(st.nextToken());
            sum += a[i];
        }
        long[] b = a.clone();
        Arrays.sort(b);  // 升序
        long keepAsc = calc(a, b);
        // 降序
        for (int i = 0; i < n/2; i++) {
            long t = b[i]; b[i] = b[n-1-i]; b[n-1-i] = t;
        }
        long keepDesc = calc(a, b);

        System.out.println((sum - keepAsc) + " " + (sum - keepDesc));
    }
}
