import sys
from collections import defaultdict

def calc(x, y):
    cnt = defaultdict(int)
    diff = 0
    keep = 0
    for a, b in zip(x, y):
        # 插入 x 的前缀元素
        before = cnt[a]
        if before != 0:
            diff -= 1
        cnt[a] = before + 1
        if cnt[a] != 0:
            diff += 1

        # 移除 y 的前缀元素
        before = cnt[b]
        if before != 0:
            diff -= 1
        cnt[b] = before - 1
        if cnt[b] != 0:
            diff += 1

        if diff == 0 and a == b:
            keep += a
    return keep

def main():
    input = sys.stdin.readline
    n = int(input())
    x = list(map(int, input().split()))
    total = sum(x)

    # 非降序（升序）
    y = sorted(x)
    keep_asc = calc(x, y)

    # 非增序（降序）
    y = sorted(x, reverse=True)
    keep_desc = calc(x, y)

    print(total - keep_asc, total - keep_desc)

if __name__ == "__main__":
    main()
